/* Department-scoped crane forms. Saves are verified atomically by the server. */
(()=>{
const labels={craneMonthlyZoom:['表單放大','Form zoom','Ampliación','Phóng to biểu mẫu'],craneMonthlyPrintHelp:['列印固定為 A4 直式，每頁保留可閱讀字級，內容較多時自動分頁。畫面放大不影響列印。','Printing uses A4 portrait with readable text and automatic pagination. Screen zoom does not change print size.','Impresión A4 vertical, texto legible y paginación automática. La ampliación de pantalla no cambia la impresión.','In A4 dọc, chữ dễ đọc và tự chia trang. Phóng to màn hình không đổi cỡ in.'],visual:['QR18-03 機器日常點檢表','QR18-03 Machine daily checklist','QR18-03 Inspección diaria de máquinas','QR18-03 Kiểm tra máy hằng ngày'],qr04:['QR18-04 預防保養記錄表','QR18-04 Preventive maintenance record','QR18-04 Registro de mantenimiento preventivo','QR18-04 Hồ sơ bảo dưỡng phòng ngừa'],cadreManage:['QR18-13 幹部日常管理點檢表','QR18-13 Cadres daily checklist','QR18-13 Lista diaria de mandos','QR18-13 Kiểm tra quản lý'],craneMonthly:['QR18-05 固定式起重機每月定期檢查表','QR18-05 Fixed crane monthly inspection','QR18-05 Inspección mensual de grúa fija','QR18-05 Kiểm tra cầu trục hằng tháng'],craneDaily:['HR07-10 固定式起重機每日檢點表','HR07-10 Fixed crane daily inspection','HR07-10 Inspección diaria de grúa fija','HR07-10 Kiểm tra cầu trục hằng ngày']};
for(const[k,v]of Object.entries(labels))translations[k]=Object.fromEntries(['zh','en','es','vi'].map((l,i)=>[l,v[i]]));
let departmentId='',equipmentId='',month=inspectionDay().slice(0,7),records=[],generation=0,country='',loaded=false,monthlyTemplate=null,monthlyZoom=100;
const isPage=()=>['craneMonthly','craneDaily'].includes(view),formKind=()=>view==='craneMonthly'?'monthly':'daily';
const ds=()=>data.departments.filter(d=>d.is_active!==false&&accessDepartment(d.id,formKind()==='monthly'?'crane_monthly':'crane_daily'));
const machines=()=>data.equipment.filter(e=>e.department_id===departmentId&&!e.archived_at&&e.machine_no&&/天車|起重機/.test(e.name_zh+' '+(e.equipment_groups?.name_zh||data.groups?.find(g=>g.id===e.equipment_group_id)?.name_zh||'')));
const equipment=()=>machines().find(e=>e.id===equipmentId);
const modelText=value=>!value||Object.values(translations.f40_16).includes(value)?formText('f40_16'):value;
const ml=v=>formContentHtml(v);
const key=()=>[activeCountry,countryGeneration,profile?.account_id,view,departmentId,equipmentId,month].join(':');
const old=renderContent;renderContent=function(){if(isPage()&&profile&&activeCountry){renderCrane();return;}generation++;return old();};
async function renderCrane(){
 const ck=activeCountry+':'+countryGeneration;if(country!==ck){country=ck;departmentId='';equipmentId='';records=[];}
 const departments=ds();if(!departments.some(d=>d.id===departmentId))departmentId=departments.find(d=>d.id===profile.department_id)?.id||departments[0]?.id||'';
 const es=machines();if(!es.some(e=>e.id===equipmentId))equipmentId=es[0]?.id||'';
 const monthly=formKind()==='monthly';loaded=false;records=[];
 $('#content').innerHTML=`<section class="crane-page"><p class="notice">${formHtml('f40_0')}</p><div class="filter-row"><label>${formHtml('f40_1')} <select id="craneDept" class="select">${departments.map(d=>`<option value="${esc(d.id)}" ${d.id===departmentId?'selected':''}>${esc(nameOf(d))}</option>`).join('')}</select></label><label>${formHtml('f40_3')} <select id="craneEquipment" class="select">${es.map(e=>`<option value="${esc(e.id)}" ${e.id===equipmentId?'selected':''}>${esc(e.machine_no)} · ${esc(nameOf(e))}</option>`).join('')}</select></label><label>${formHtml('f40_4')} <input id="craneMonth" class="select" type="month" min="2000-01" max="2099-12" value="${month}"></label><button id="craneReload" class="btn secondary">${formHtml('f40_5')}</button><button id="craneEdit" class="btn primary" disabled>${monthly?formText('f40_6'):formText('f40_7')}</button><button id="cranePrint" class="btn secondary" disabled>${formHtml('f40_8')}</button></div><p id="craneMessage" role="status"></p><div id="craneSheet"></div></section>`;
 $('#craneDept').onchange=e=>{departmentId=e.target.value;equipmentId='';renderCrane();};$('#craneEquipment').onchange=e=>{equipmentId=e.target.value;renderCrane();};$('#craneMonth').onchange=e=>{if(/^20\d{2}-(0[1-9]|1[0-2])$/.test(e.target.value)){month=e.target.value;renderCrane();}};$('#craneReload').onclick=renderCrane;
 $('#craneEdit').onclick=()=>openRecord(monthly?records[0]?.inspection_date||(month===inspectionDay().slice(0,7)?inspectionDay():month+'-01'):(month===inspectionDay().slice(0,7)?inspectionDay():month+'-01'));
 if(monthly){$('#cranePrint').insertAdjacentHTML('afterend',`<label>${txt('craneMonthlyZoom')}<select class="select" id="craneMonthlyZoom">${[100,115,130,150].map(n=>`<option value="${n}" ${monthlyZoom===n?'selected':''}>${n}%</option>`).join('')}</select></label>`);$('#craneMonthlyZoom').onchange=e=>{monthlyZoom=Number(e.target.value);$('#craneSheet').style.setProperty('--crane-monthly-zoom',monthlyZoom/100);};$('#craneSheet').style.setProperty('--crane-monthly-zoom',monthlyZoom/100);$('#craneMessage').insertAdjacentHTML('beforebegin',`<p class="crane-monthly-print-help">${txt('craneMonthlyPrintHelp')}</p>`);}
 $('#cranePrint').onclick=()=>{document.body.classList.add('printing-crane');window.print();document.body.classList.remove('printing-crane');};
 if(!equipmentId){$('#craneMessage').textContent=formText('f40_9');return;}
 const ticket=++generation,requestKey=key();$('#craneMessage').textContent=formText('f40_10');
 try{const r=await api({action:'crane_month',equipment_id:equipmentId,kind:formKind(),month});if(ticket!==generation||requestKey!==key())return;records=r.records;monthlyTemplate=r.template;loaded=true;draw();$('#cranePrint').disabled=false;$('#craneEdit').disabled=month>inspectionDay().slice(0,7);$('#craneMessage').textContent=formKind()==='daily'?formText('f40_11'):formText('f40_12');}catch(e){if(ticket===generation&&isPage())$('#craneMessage').textContent=formText('f40_13');}
}
function header(title){const e=equipment();return `<header class="crane-paper-head"><img src="/cadre-logo.png" alt="NES Limited"><h2>${txt(title)}</h2></header><div class="crane-metadata"><span>${formHtml('f40_2')}：${esc(nameOf(ds().find(d=>d.id===departmentId)))}</span><span>${formHtml('f40_3')}：${esc(e.machine_no)}</span><span>${formHtml('f40_14')}：${month}</span></div>`;}
function ropeMeasurementsMarkup(result){const m=result?.diameter_measurements||{};return [10,12].filter(n=>m[n]!==undefined&&m[n]!==null&&String(m[n]).trim()!=='').map(n=>`<div class="crane-measure-display">${esc(t('craneRopeMeasured'))} ${n}mm：${esc(m[n])}mm</div>`).join('');}
function draw(){
 const monthly=formKind()==='monthly',template=CRANE_TEMPLATE[formKind()];
 if(monthly){const r=records[0],d=r?.details||{},items=r?.template_snapshot||monthlyTemplate?.items||template.items;
  $('#craneSheet').innerHTML=`<div class="crane-scroll"><article class="crane-paper monthly">${header('craneMonthly')}<div class="crane-metadata"><span>${formHtml('f40_15')}：${esc(modelText(d.model))}</span><span>${formHtml('f40_18')}：${esc(d.capacity||'—')}</span><span>${formHtml('f40_19')}：${esc(r?.inspection_date||'—')}</span><span>${formHtml('f40_20')}</span></div><table class="crane-table"><colgroup><col style="width:25%"><col style="width:65%"><col style="width:10%"></colgroup><thead><tr><th>${formHtml('f40_21')}</th><th>${formHtml('f40_22')}</th><th>${formHtml('f40_23')}</th></tr></thead><tbody>${items.map((x,i)=>{const start=i===0||x.name.zh!==items[i-1].name.zh,n=(()=>{let n=1;while(i+n<items.length&&items[i+n].name.zh===x.name.zh)n++;return n;})();return `<tr>${start?`<th rowspan="${n}">${ml(x.name)}</th>`:''}<td>${ml(x.standard)}${Number(x.id)===7?ropeMeasurementsMarkup(r?.results?.[i]):''}${cranePhotoMarkup(x,equipmentId,r?.id)}</td><td class="crane-symbol">${esc(r?.results[i]?.value||'')}</td></tr>`;}).join('')}</tbody></table><div class="crane-hazards">${['hazard','risk','measures','suitability'].map((k,i)=>`<section><strong>${ml(template.hazards[i])}</strong><p>${esc(d[k]||'')}</p></section>`).join('')}</div><div class="crane-bottom"><div class="crane-source-notes">${formContentHtml(FORM_TEMPLATE_NOTES[formKind()])}</div><div><p>${formHtml('f40_24')}：${esc(r?.inspector_name||'')}</p><p>${formHtml('f40_25')}：${esc(r?.supervisor_name||'')}</p><p>${r?.confirmed_at?formText('f40_26'):r?.completed?formText('f40_27'):r?formText('f40_28'):formText('f40_29')}</p></div></div><footer>${template.code}</footer></article></div>`;
 }else{const days=Array.from({length:31},(_,i)=>i+1),n=new Date(+month.slice(0,4),+month.slice(5),0).getDate(),byDay=new Map(records.map(r=>[+r.inspection_date.slice(8),r]));
  const button=(day,value='')=>`<button data-crane-day="${day}" ${day>n||month+'-'+String(day).padStart(2,'0')>inspectionDay()?'disabled':''} aria-label="${month}-${String(day).padStart(2,'0')} ${esc(value||formText('f40_30'))}">${esc(value)}</button>`;
  $('#craneSheet').innerHTML=`<div class="crane-scroll"><article class="crane-paper daily"><div class="crane-company">${formHtml('f40_73')}</div>${header('craneDaily')}<p>${formHtml('f40_31')}：${esc(records.at(-1)?.details?.location||equipment().location||'—')}</p><table class="crane-table"><colgroup><col style="width:45px"><col style="width:310px">${days.map(()=>'<col style="width:38px">').join('')}</colgroup><thead><tr><th rowspan="2">${formHtml('f40_32')}</th><th rowspan="2">${formHtml('f40_33')}</th><th colspan="31">${formHtml('f40_34')}</th></tr><tr>${days.map(day=>`<th class="${day>n?'unused':''}">${button(day,String(day))}</th>`).join('')}</tr></thead><tbody>${template.items.map((it,i)=>`<tr><th>${it.id}</th><td>${ml(it.name)}</td>${days.map(day=>`<td class="crane-symbol ${day>n?'unused':''}">${button(day,day>n?'—':byDay.get(day)?.results[i]?.value||'')}</td>`).join('')}</tr>`).join('')}<tr><th colspan="2">${formHtml('f40_35')}</th><td colspan="31" class="crane-measures">${records.filter(r=>r.details.measures).map(r=>`<p>${r.inspection_date.slice(8)} ${formHtml('f40_43')}：${esc(r.details.measures)}</p>`).join('')}</td></tr><tr><th colspan="2">${formHtml('f40_36')}</th><td colspan="31" class="crane-source-notes">${formContentHtml(FORM_TEMPLATE_NOTES[formKind()])}</td></tr></tbody></table><div class="crane-daily-signs">${[['supervisor_name',formText('f40_37')],['leader_name',formText('f40_38')],['inspector_name',formText('f40_40')]].map(([k,label])=>`<div><strong>${label}</strong>${records.filter(r=>r[k]).map(r=>`<span>${r.inspection_date.slice(8)} ${formHtml('f40_43')}：${esc(r[k])}${k==='inspector_name'&&!r.completed?formText('f40_42'):''}</span>`).join('')}</div>`).join('')}</div><footer>${template.code}</footer></article></div>`;
  $$('[data-crane-day]').forEach(b=>b.onclick=()=>openRecord(month+'-'+b.dataset.craneDay.padStart(2,'0')));
 }
 if(monthly)bindCranePhotos($('#craneSheet'));
}
function openRecord(date){
 if(!loaded||date>inspectionDay())return;
 const requestKey=key(),savedEquipment=equipmentId,kind=formKind(),monthly=kind==='monthly',template=CRANE_TEMPLATE[kind],r=records.find(x=>monthly||x.inspection_date===date),details=r?.details||{};
 const items=monthly?(r?.template_snapshot||monthlyTemplate?.items||template.items):template.items;
 const symbols=monthly?['','✔','Δ','X','─']:['','ˇ','×'];let saving=false,dirty=false;
 const dialog=document.createElement('div');dialog.className='modal open crane-modal';
 const field=(name,label,value,max=100,type='text')=>`<label>${label}<input name="${name}" type="${type}" maxlength="${max}" value="${esc(value||'')}" ${name==='date'?`min="${month}-01" max="${month===inspectionDay().slice(0,7)?inspectionDay():month+'-'+new Date(+month.slice(0,4),+month.slice(5),0).getDate()}" required`:''}></label>`;
 dialog.innerHTML=`<section class="dialog" role="dialog" aria-modal="true" aria-labelledby="craneDialogTitle"><header class="dialog-head"><div><h2 id="craneDialogTitle">${txt(monthly?'craneMonthly':'craneDaily')}</h2><p>${esc(equipment().machine_no)} · ${esc(nameOf(ds().find(d=>d.id===departmentId)))}</p></div><button id="craneClose" class="x" aria-label="${esc(formText('f40_44'))}">×</button></header><form id="craneForm"><div class="dialog-body">${monthly?field('date',formText('f40_19'),r?.inspection_date||date,10,'date'):`<h3>${date}</h3>`}<p>${monthly?formText('f40_45'):formText('f40_46')}</p>${monthly?field('model',formText('f40_15'),modelText(details.model))+field('capacity',formText('f40_17'),details.capacity):field('location',formText('f40_31'),details.location||equipment().location,300)}${monthly?`<button type="button" class="btn secondary crane-quick-complete" id="craneQuickComplete">${esc(t('craneQuickComplete'))}</button><p class="crane-quick-help">${esc(t('craneQuickCompleteHelp'))}</p>`:''}${items.map((it,i)=>{const measured=r?.results?.[i]?.diameter_measurements||{};return `<section class="item"><h3>${it.id}. ${ml(it.name)}</h3>${it.standard?`<p>${ml(it.standard)}</p>`:''}${monthly&&Number(it.id)===7?`<div class="crane-measure-inputs"><label>${esc(t('craneRope10'))}<input type="number" inputmode="decimal" min="0" step="0.01" name="diameter10" data-rope-measure="10" value="${esc(measured[10]??'')}"></label><label>${esc(t('craneRope12'))}<input type="number" inputmode="decimal" min="0" step="0.01" name="diameter12" data-rope-measure="12" value="${esc(measured[12]??'')}"></label></div>`:''}${monthly?cranePhotoMarkup(it,savedEquipment,r?.id):''}<label>${formHtml('f40_34')}<select class="select" name="result${i}">${symbols.map(s=>`<option value="${s}" ${s===(r?.results[i]?.value||'')?'selected':''}>${s||formText('f40_30')}</option>`).join('')}</select></label></section>`;}).join('')}${(monthly?['hazard','risk','measures','suitability']:['measures']).map((k,i)=>`<label>${monthly?ml(template.hazards[i]):formText('f40_35')}<textarea name="${k}" maxlength="3000" rows="3">${esc(details[k]||'')}</textarea></label>`).join('')}${field('inspector',formText('f40_39'),r?.inspector_name)}${canManage()?(monthly?'':field('leader',formText('f40_38'),r?.leader_name))+field('supervisor',formText('f40_41'),r?.supervisor_name):''}<label class="crane-check"><input type="checkbox" name="completed">${formHtml('f40_47')}</label>${canManage()?`<label class="crane-check"><input type="checkbox" name="confirmed">${formHtml('f40_48')}</label>`:''}<p class="notice">${formHtml('f40_49')}</p><p id="craneSaveMessage" role="alert"></p></div><footer class="dialog-foot"><button class="btn primary" type="submit">${formHtml('f40_50')}</button></footer></form></section>`;
 document.body.append(dialog);bindCranePhotos(dialog);const f=dialog.querySelector('form'),close=()=>{if(!saving&&(!dirty||confirm(formText('f40_51'))))dialog.remove();};$('#craneClose').onclick=close;dialog.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();close();}};
 const syncRopeMeasurement=()=>{if(!monthly)return;const values=[['diameter10',9.3],['diameter12',11.16]].filter(([name])=>f.elements[name].value.trim()!=='').map(([name,min])=>Number(f.elements[name].value)>=min);if(values.length)f.elements['result6'].value=values.every(Boolean)?'✔':'X';};
 const quickComplete=$('#craneQuickComplete');if(quickComplete)quickComplete.onclick=()=>{items.forEach((it,i)=>{f.elements['result'+i].value='✔';});syncRopeMeasurement();f.elements.completed.checked=true;dirty=true;$('#craneSaveMessage').textContent='';};
 f.oninput=e=>{dirty=true;if(!['completed','confirmed'].includes(e.target.name)){f.elements.completed.checked=false;if(f.elements.confirmed)f.elements.confirmed.checked=false;}if(e.target.dataset.ropeMeasure)syncRopeMeasurement();};
 f.onsubmit=async event=>{event.preventDefault();if(saving||key()!==requestKey)return;
  const results=items.map((it,i)=>{const result={id:it.id,value:f.elements['result'+i].value};if(monthly&&Number(it.id)===7)result.diameter_measurements={10:f.elements.diameter10.value.trim(),12:f.elements.diameter12.value.trim()};return result;}),inspector=f.elements.inspector.value.trim(),supervisor=f.elements.supervisor?.value.trim()||'',completed=f.elements.completed.checked,confirmed=!!f.elements.confirmed?.checked;
  const ropeReadings=results.find(x=>Number(x.id)===7)?.diameter_measurements||{};
  if(!inspector||(completed&&results.some(x=>!x.value))||(completed&&monthly&&!Object.values(ropeReadings).some(x=>x!==''&&Number.isFinite(Number(x))))||(confirmed&&(!completed||!supervisor))){$('#craneSaveMessage').textContent=completed&&monthly&&!Object.values(ropeReadings).some(x=>x!==''&&Number.isFinite(Number(x)))?t('craneRopeMeasurementRequired'):formText('f40_52');return;}
  const info=Object.fromEntries((monthly?['model','capacity','hazard','risk','measures','suitability']:['location','measures']).map(k=>[k,f.elements[k].value.trim()]));
  saving=true;dialog.querySelectorAll('button,input,select,textarea').forEach(x=>x.disabled=true);
  try{const saved=await api({action:'crane_save',equipment_id:savedEquipment,kind,inspection_date:monthly?f.elements.date.value:date,revision:r?.revision||0,template_revision:monthly?(r?.template_revision??monthlyTemplate?.revision??0):0,results,details:info,inspector_name:inspector,leader_name:f.elements.leader?.value.trim()||'',supervisor_name:confirmed?supervisor:'',completed,confirmed});if(key()!==requestKey)return;records=records.filter(x=>x.id!==saved.record.id);records.push(saved.record);records.sort((a,b)=>a.inspection_date.localeCompare(b.inspection_date));dialog.remove();draw();$('#craneMessage').textContent=confirmed?formText('f40_53'):completed?formText('f40_54'):formText('f40_55');}
  catch(e){$('#craneSaveMessage').textContent=e.message.includes('template_changed')?t('craneTemplateChanged'):e.message.includes('record_changed')?formText('f40_56'):e.message.includes('forbidden')?formText('f40_57'):formText('f40_58');}
  finally{saving=false;dialog.querySelectorAll('button,input,select,textarea').forEach(x=>x.disabled=false);}
 };
}
})();
